package bowling

import "errors"

// Game keeps track of a bowling game in progress.
type Game struct {
	rolls       []int
	frame       int // current frame index, 0-9; 10 once the game is over
	rollInFrame int // 0, 1, or 2 (2 only in the final frame)
}

// NewGame returns a new, empty Game.
func NewGame() *Game {
	return &Game{}
}

// Roll records a roll of `pins` pins and validates it against the current
// state of the game.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errors.New("Negative roll is invalid")
	}
	if pins > 10 {
		return errors.New("Pin count exceeds pins on the lane")
	}
	if g.frame > 9 {
		return errors.New("Cannot roll after game is over")
	}

	if g.frame < 9 {
		if g.rollInFrame == 1 {
			if pins > 10-g.rolls[len(g.rolls)-1] {
				return errors.New("Pin count exceeds pins on the lane")
			}
		}
	} else {
		switch g.rollInFrame {
		case 1:
			first := g.rolls[len(g.rolls)-1]
			if first < 10 && pins > 10-first {
				return errors.New("Pin count exceeds pins on the lane")
			}
		case 2:
			second := g.rolls[len(g.rolls)-1]
			if second < 10 && pins > 10-second {
				return errors.New("Pin count exceeds pins on the lane")
			}
		}
	}

	g.rolls = append(g.rolls, pins)
	g.advance()
	return nil
}

// advance updates the frame/rollInFrame state after a roll has been recorded.
func (g *Game) advance() {
	if g.frame < 9 {
		if g.rollInFrame == 0 && g.rolls[len(g.rolls)-1] == 10 {
			g.frame++
			g.rollInFrame = 0
		} else {
