package bowling

import "errors"

// Game keeps track of a bowling game in progress.
type Game struct {
	rolls       []int // every roll, in order
	frame       int   // current frame index, 0-9; 10 once the game is over
	rollInFrame int   // 0, 1, or 2 (2 only in the final frame)
}

// NewGame returns a new, empty Game.
func NewGame() *Game {
	return &Game{}
}

// Roll records a roll that knocked down `pins` pins, validating it against
// the current state of the game.
func (g *Game) Roll(pins int) error {
	if pins < 0 {
		return errors.New("Negative roll is invalid")
	}
	if pins > 10 {
		return errors.New("Pin count exceeds pins on the lane")
	}
	if g.frame > 9 {
		return errors.New("Cannot roll after game is over")
	}

	if g.frame < 9 {
		// Frames 1-9: the second roll may not exceed the pins left standing.
		if g.rollInFrame == 1 && pins > 10-g.rolls[len(g.rolls)-1] {
			return errors.New("Pin count exceeds pins on the lane")
		}
	} else {
		// Frame 10.
		switch g.rollInFrame {
		case 1:
			first := g.rolls[len(g.rolls)-1]
			// After a strike the lane is reset; otherwise the second roll
			// may not exceed the pins left standing.
			if first < 10 && pins > 10-first {
				return errors.New("Pin count exceeds pins on the lane")
			}
		case 2:
			first := g.rolls[len(g.rolls)-2]
			second := g.rolls[len(g.rolls)-1]
			// The third roll shares the lane with the second only when the
			// first roll was a strike and the second was not.
			if first == 10 && second < 10 && pins > 10-second {
				return errors.New("Pin count exceeds pins on the lane")
			}
		}
	}

	g.rolls = append(g.rolls, pins)
	g.advance()
	return nil
}

// advance updates the frame state after a roll has been recorded.
func (g *Game) advance() {
	last := g.rolls[len(g.rolls)-1]
	if g.frame < 9 {
		if g.rollInFrame == 1 || last == 10 {
			g.frame++
			g.rollInFrame = 0
		} else {
			g.rollInFrame = 1
		}
		return
	}
	switch g.rollInFrame {
	case 0:
		g.rollInFrame = 1
	case 1:
		first := g.rolls[len(g.rolls)-2]
		// A strike or a spare in the tenth frame earns a bonus roll;
		// an open frame ends the game.
		if first == 10 || first+last == 10 {
			g.rollInFrame = 2
		} else {
			g.frame = 10
		}
	default:
		g.frame = 10
	}
}

// Score returns the total score of the game, or an error if the game is not
// yet complete.
func (g *Game) Score() (int, error) {
	if g.frame < 10 {
		return 0, errors.New("Score cannot be taken until the end of the game")
	}
	rolls := g.rolls
	total := 0
	i := 0
	for frame := 0; frame < 10; frame++ {
		switch {
		case rolls[i] == 10: // strike: bonus is the next two rolls
			total += 10 + rolls[i+1] + rolls[i+2]
			i++
		case rolls[i]+rolls[i+1] == 10: // spare: bonus is the next roll
			total += 10 + rolls[i+2]
			i += 2
		default: // open frame
			total += rolls[i] + rolls[i+1]
			i += 2
		}
	}
	return total, nil
}
